/*Paragraph*/
.balance {
  text-wrap: balance;
}
.pretty {
  text-wrap: pretty;
}

.opacity-80 {
  opacity: 0.8;
}

.b-700 {
    font-weight: 700 !important;
}

/*Padding*/
.p-section {
  padding: 120px 20px;
}

.py-0 {
  padding-top: 0px;
  padding-bottom: 0px;
}

.pt-0 {
  padding-top: 0px;
}

.p2-section {
  padding-top: 80px !important;
  padding-left: 20px !important;
  padding-bottom: 120px !important;
  padding-right: 20px !important;
}

