 padding-bottom: 28px !important;
 padding-right: 0px !important;
 overflow-y: hidden;
}

selector .elementor-nav-menu--dropdown ul li:last-child {
 padding-bottom: 0px !important;
}

/* Remove default value */
selector .elementor-nav-menu--dropdown ul li a {
 padding-top: 0px !important;
 padding-left: 0px !important;
 padding-bottom: 0px !important;
 padding-right: 0px !important;
}

selector .elementor-nav-menu--dropdown ul li a:hover {
 color: #FF5F00;
 opacity: 1;
}

