 background-color: rgba(255, 255, 255, 0) !important;
}

selector .elementor-nav-menu--dropdown .elementor-item.highlighted,
selector .elementor-nav-menu--dropdown .elementor-item:focus,
selector .elementor-nav-menu--dropdown .elementor-item:hover {
