  margin: 0 !important;
}

.forminator-ui.forminator-custom-form[data-design="flat"]:not(
    .forminator-size--small
  ) {
  margin: 0 !important;
}

.forminator-ui.forminator-custom-form[data-design="flat"] {
  margin: 0 !important;
}

/* Form Wrapper */
.forminator-custom-form {
  font-family: var(--global-font-family);
  font-size: var(--text-lg-global);
  font-weight: var(--global-font-weight);
  background-color: #ffffff;
  padding: 2rem;
  border-radius: 1.5rem;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.05);
  max-width: 600px;
  margin: auto;
}

.forminator-row {
  margin-bottom: 0 !important;
}

/* Form Fields */
.forminator-field {
  margin-bottom: 1.5rem;
}
/* .forminator-col .forminator-field {
  margin-bottom: 0;
} */

/* Field Labels */
.forminator-label {
  font-family: var(--e-global-typography-9c0bb5a-font-family), Sans-serif;
  font-size: var(--text-lg-global);
  font-weight: var(--global-font-weight);
  color: #101820;
  margin-bottom: 0.5rem;
  display: block;
  display: none;
}

/* Input, Textarea, Select */
.forminator-input,
.forminator-textarea,
.forminator-select {
  width: 100%;
  font-size: var(--text-lg-global);
  color: #fff;
  padding: 22px 32px;
  border: 1px solid #40444c;
  border-radius: 8px;
  background-color: #121b24;
  transition: border-color 0.3s, box-shadow 0.3s;
}

.forminator-input:focus,
.forminator-textarea:focus,
.forminator-select:focus {
  border-color: #fff;
  /* box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1); */
  outline: none;
}

/* Submit Button */
.forminator-button-submit {
  font-size: var(--text-lg-global);
  font-weight: var(--global-font-weight);
  background-color: #ff5f00;
  color: #fff;
  border: none;
  padding: 0.75rem 2.5rem;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.3s, transform 0.2s;
  margin-top: 20px !important;
  margin-bottom: 0 !important;
}

.forminator-button-submit:hover {
  background-color: #cc4302;
  color: #fff;
  /* transform: translateY(-2px); */
  box-shadow: none !important;
}

/* Checkboxes and Radio */
.forminator-checkbox,
.forminator-radio {
  margin-bottom: 1rem;
}

.forminator-checkbox input:checked + span,
.forminator-radio input:checked + span {
  font-weight: 600;
  color: #4f46e5;
}

.forminator-ui.forminator-custom-form[data-design="flat"]
  .forminator-error-message {
  border-radius: var(--global-border-radius);
}

/* Error Messages */
.forminator-error-message {
  color: #e11d48;
  font-size: 0.875rem;
  margin-top: 0.25rem;
}

/* Success Message */
.forminator-response-message.forminator-success {
  background-color: #d1fae5;
  color: #065f46;
  padding: 1rem;
  border-radius: 0.75rem;
  margin-top: 1.5rem;
