 justify-content: space-between;
 align-items: center;
 flex-direction: row;
 gap: 32px;
 padding: 24px;
 background-color: #121B24;
 border-radius: 8px;
 transition: all 0.3s;
}

selector #whr_embed_hook li.whr-item:hover {
